B.acv=new A.dI("q_tali_sword","Wooden Sword","quest",null,"grey","",B.aO,0,0,"any","Small, sticky, and very much loved.","quest",0,!1)
B.acK=new A.dI("q_riverbloom","Riverbloom","quest",null,"grey","",B.aO,0,0,"any","A pale river flower. Mira needs three.","quest",0,!1)
B.acL=new A.dI("q_bent_antler","Snapped Antler","quest",null,"grey","",B.aO,0,0,"any","Broken running, not fighting.","quest",0,!1)
B.acx=new A.dI("q_torn_satchel","Torn Satchel","quest",null,"grey","",B.aO,0,0,"any","Renn's. A sealed letter is still inside.","quest",0,!1)
B.acy=new A.dI("q_sealed_letter","Sealed Letter","quest",null,"grey","",B.aO,0,0,"any","Pell says it is about grain.","quest",0,!1)
B.acD=new A.dI("q_folded_reply","Folded Reply","quest",null,"grey","",B.aO,0,0,"any","For Pell. It is not about grain either.","quest",0,!1)
B.acM=new A.dI("q_ferry_bell","Dented Bell","quest",null,"grey","",B.aO,0,0,"any","Small and brass. It belongs at the landing.","quest",0,!1)
B.acA=new A.dI("q_gnawed_sack","Empty Ration Sack","quest",null,"grey","",B.aO,0,0,"any","Those are knife cuts, not teeth.","quest",0,!1)
B.acI=new A.dI("q_ration_ledger","Warden's Ledger","quest",null,"grey","",B.aO,0,0,"any","Every missing sack, in Kessa's hard hand.","quest",0,!1)
